-- 0039 表单字段与升级续报（P1-06 / P1-09 / P1-13 / P1-16）
-- F2：上报对象改单选 + 同步抄送 + 初报/续报/终报 + 个人信息字段；
-- F12：补个人信息影响与告知字段；F3：评估人拆分为信息科评估 + 医务处会签；
-- F8：补 MTTD/MTTI/MTTR/RTO/RPO/双报及时率/证据完整率/干扰项数/问题清单；
-- S02-3/S06-3/S08-3 补充「影响扩大按等级升级并续报」口径。纯 DML，固定终值，可重复执行。

UPDATE form_templates
   SET fields = '[{"label":"上报单位","hint":"填写医院全称，与系统单位名称一致。","required":true,"type":"text"},{"label":"事件类型","hint":"如勒索病毒、DDoS 攻击、数据泄露、系统宕机等。","required":true,"type":"select","options":["勒索病毒","DDoS 攻击","数据泄露","系统宕机","钓鱼邮件","内网渗透","其他"]},{"label":"事件等级","hint":"按预案分为特别重大/重大/较大/一般，与研判结论一致。","required":true,"type":"select","options":["特别重大","重大","较大","一般"]},{"label":"报告类型","hint":"初报为首次报送；续报为进展更新；终报为闭环报告。","required":true,"type":"select","options":["初报","续报","终报"]},{"label":"发生时间","hint":"事件实际发生时间；无法确认时填写首次发现时间并注明。","required":true,"type":"datetime"},{"label":"发现时间","hint":"首次发现事件的时间，精确到分钟。","required":true,"type":"datetime"},{"label":"受攻击系统","hint":"被攻击或受影响的业务系统名称。","required":true,"type":"text"},{"label":"IP/域名","hint":"受攻击资产 IP、域名或端口，多个用顿号分隔。","required":true,"type":"text"},{"label":"事件基本情况","hint":"按「何时、何地、何事、如何发现」叙述事件经过。","required":true,"type":"textarea"},{"label":"影响范围","hint":"受影响业务系统、科室、患者服务与数据范围（演练虚拟数据）。","required":true,"type":"textarea"},{"label":"已采取措施","hint":"已执行的隔离、封堵、停机、备份等处置动作及时间。","required":true,"type":"textarea"},{"label":"处置进展","hint":"当前处置阶段与预计完成时间。","required":true,"type":"textarea"},{"label":"下一步计划","hint":"拟开展的溯源、恢复、整改等计划安排。","required":true,"type":"textarea"},{"label":"报送人/联系电话","hint":"报送人姓名 + 虚拟联系电话。","required":true,"type":"text"},{"label":"上报对象","hint":"单次报送只选一个接收单位；向市卫生健康局、市网信办双报时请分别提交两份表单，可并行。","required":true,"type":"select","options":["市卫生健康局","市网信办","市网安大队","院应急指挥部"]},{"label":"同步抄送","hint":"院内抄送对象（可多选），仅内部知会，不改变上报对象。","required":false,"type":"multiselect","options":["院应急指挥部","医务处","院办","信息科","财务处","收费处"]},{"label":"时限依据","hint":"引用的上报时限条款，如重大事件 1 小时内。","required":true,"type":"text"},{"label":"签发人","hint":"负责签发本次上报材料的院领导或信息科负责人。","required":true,"type":"text"},{"label":"回执编号","hint":"接收单位反馈的回执编号，未取得可留空。","required":false,"type":"text"},{"label":"报送时间","hint":"实际报送时间，精确到分钟。","required":true,"type":"datetime"},{"label":"是否涉及个人信息","hint":"按实际情况选择；不确定时选「待核实」，核实后补报。","required":true,"type":"select","options":["是","否","待核实"]},{"label":"是否涉及敏感个人信息","hint":"医疗健康、行踪轨迹等属敏感个人信息。","required":true,"type":"select","options":["是","否","待核实"]},{"label":"涉及人数（估算）","hint":"仅填写演练虚拟数量，不得录入真实患者信息。","required":false,"type":"text"},{"label":"是否已履行告知","hint":"涉及个人信息的，说明是否已按《个人信息保护法》告知监管与个人。","required":true,"type":"select","options":["是","否","不适用","待评估"]},{"label":"告知渠道","hint":"如短信、电话、公告、监管平台；未告知可留空。","required":false,"type":"text"}]'
 WHERE id = 'F2';

UPDATE form_templates
   SET fields = '[{"label":"发现时间","hint":"以告警平台或值班记录中首次发现的时间为准，精确到分钟。","required":true,"type":"datetime"},{"label":"发现渠道","hint":"本次事件的发现来源。","required":true,"type":"select","options":["安全告警系统","人工巡检","临床科室报告","外部单位通报","第三方监测","其他"]},{"label":"受影响对象/系统","hint":"涉及的系统、主机、账号或业务环节，仅演练虚拟数据。","required":true,"type":"text"},{"label":"影响数量","hint":"受影响对象数量，如账号数、主机台数。","required":true,"type":"text"},{"label":"是否仍在扩散","hint":"选择当前是否仍在持续扩散或持续登录。","required":true,"type":"select","options":["是","否","无法确认"]},{"label":"临时措施","hint":"已采取的临时处置，如限制登录、暂停访问，注明执行人与时间。","required":true,"type":"textarea"},{"label":"核实人","hint":"完成核实的人员姓名与岗位。","required":true,"type":"text"},{"label":"核实时间","hint":"完成核实的时间，精确到分钟。","required":true,"type":"datetime"},{"label":"证据材料","hint":"支撑核实结论的日志、截图、单据名称。","required":false,"type":"textarea"},{"label":"是否涉及个人信息","hint":"按账号、患者、员工数据实际范围选择。","required":true,"type":"select","options":["是","否","待核实"]},{"label":"是否涉及敏感个人信息","hint":"医疗健康、身份证明、行踪轨迹等。","required":true,"type":"select","options":["是","否","待核实"]},{"label":"涉及人数（估算）","hint":"仅填写演练虚拟数量。","required":false,"type":"text"},{"label":"是否已通知监管/个人","hint":"涉及个人信息的，说明是否已履行告知义务。","required":true,"type":"select","options":["是","否","不适用","待评估"]},{"label":"告知渠道与时间","hint":"如短信、电话、公告、监管平台及时间。","required":false,"type":"text"}]'
 WHERE id = 'F12';

UPDATE form_templates
   SET fields = '[{"hint":"勾选本次事件实际受影响的业务系统（可多选），提交后驱动大屏/看板业务影响状态。","type":"multiselect","label":"受影响业务系统","options":["HIS收费系统","医护工作站","电子病历系统","临床检验系统","医学影像系统","办公OA系统"],"required":1},{"hint":"格式如 2026-10-24 09:00 至 10:30；仍在中断填「持续中」。","type":"text","label":"业务中断起止时间","required":true},{"hint":"受影响的临床、医技与窗口科室。","type":"textarea","label":"受影响科室","required":true},{"hint":"仅填写演练虚拟数量，不得录入真实患者信息。","type":"text","label":"受影响患者数（虚拟）","required":true},{"hint":"按预案条款与影响评估给出建议事件等级，与上报表保持一致。","type":"select","label":"建议等级","options":["一般","较大","重大","特别重大"],"required":true},{"hint":"逐条写明影响系统、患者安全、数据量、扩散趋势四类依据及来源节点。","type":"textarea","label":"定级依据","required":true},{"hint":"评估本次事件对患者诊疗与生命安全的影响程度。","type":"select","label":"患者安全影响","options":["无影响","潜在风险","已影响诊疗","危及生命安全"],"required":true},{"hint":"按核心业务中断项数估算，如 60%（仅演练虚拟数据）。","type":"text","label":"关键业务中断比例","required":true},{"hint":"如纸质处方、人工挂号收费、手工登记，注明启动条件。","type":"textarea","label":"关键业务兜底方案","required":true},{"hint":"预计业务恢复时间。","type":"datetime","label":"预计恢复时间","required":true},{"hint":"填写信息科/网络安全管理员评估人；业务影响由医务处会签。","type":"text","label":"评估人（信息科/网安）","required":true},{"hint":"由医务处填写患者安全与业务影响会签意见。","type":"text","label":"业务影响会签人（医务处）","required":true},{"hint":"会签完成时间。","type":"datetime","label":"会签时间","required":true},{"hint":"评估完成时间。","type":"datetime","label":"评估时间","required":true},{"hint":"本节点确认后的最终事件等级，须与上报表、启动申请保持一致。","type":"select","label":"最终定级","options":["一般","较大","重大","特别重大"],"required":true},{"hint":"写明确认定级的依据、结论与后续启动建议，供审批节点引用。","type":"textarea","label":"研判结论","required":true}]'
 WHERE id = 'F3';

UPDATE form_templates
   SET fields = '[{"hint":"被攻击或受影响的系统名称及版本，多个用顿号分隔。","type":"textarea","label":"受攻击系统","required":true},{"hint":"受攻击资产 IP、域名、端口，多个用顿号分隔。","type":"textarea","label":"IP/域名","required":true},{"hint":"简述发生时间、发现方式、攻击手法与事件等级。","type":"textarea","label":"事件基本情况","required":true},{"key":"incident_level","hint":"按预案确认的事件等级。","type":"select","label":"定级结论","options":["Ⅰ级","Ⅱ级","Ⅲ级","Ⅳ级"],"required":true},{"hint":"受影响业务、科室、数据与患者服务范围（演练虚拟数据）。","type":"textarea","label":"事件影响范围","required":true},{"hint":"按时间顺序记录隔离、封堵、取证、恢复等动作及执行人。","type":"textarea","label":"现场处置过程","required":true},{"key":"response_timeline","hint":"按时间顺序记录关键处置节点与完成时刻。","type":"textarea","label":"处置时间线","required":true},{"hint":"处置成效、业务恢复情况与残留风险。","type":"textarea","label":"事件处置结果","required":true},{"key":"rectify_owner","hint":"整改事项的责任部门与责任人。","type":"text","label":"整改责任人","required":true},{"key":"retest_result","hint":"恢复后复测结果、残留风险与是否通过。","type":"textarea","label":"复测结论","required":true},{"hint":"整改措施、责任部门、完成时限与复查安排。","type":"textarea","label":"下一步整改及工作计划","required":true},{"hint":"从技术、管理、流程三方面写明本次事件的直接原因与根本原因。","type":"textarea","label":"根因分析","required":true},{"hint":"总结本次处置中有效的做法与暴露的短板，注明对应节点。","type":"textarea","label":"经验教训","required":true},{"hint":"提出可落地的整改建议与责任部门，与「下一步整改及工作计划」区分：本栏重建议，后者重排期。","type":"textarea","label":"改进建议","required":true},{"hint":"从发现到首次研判的分钟数（MTTD）。","type":"text","label":"发现时长 MTTD（分钟）","required":true},{"hint":"从发现到定级/启动的分钟数（MTTI）。","type":"text","label":"研判定级时长 MTTI（分钟）","required":true},{"hint":"从启动到核心业务恢复的分钟数（MTTR）。","type":"text","label":"业务恢复时长 MTTR（分钟）","required":true},{"hint":"恢复后允许丢失的数据时长（RPO，分钟）。","type":"text","label":"数据恢复点 RPO（分钟）","required":true},{"hint":"按剧本时限统计的按期上报比例。","type":"text","label":"上报及时率（%）","required":true},{"hint":"按应归档证据清单统计的完整比例。","type":"text","label":"证据完整率（%）","required":true},{"hint":"向市卫生健康局、市网信办双报的完成时刻，如 10:35/10:38。","type":"text","label":"双报完成时间","required":true},{"hint":"本次演练中误选的干扰项数量。","type":"text","label":"误选干扰项数（个）","required":true},{"hint":"按发现/研判/启动/处置/上报/恢复/取证协同/整改分组列明问题、责任人与时限。","type":"textarea","label":"复盘问题清单","required":true}]'
 WHERE id = 'F8';

-- 幂等：仅当 descr 尚未包含该口径时追加，版本行被清理或手工重放时不会重复叠加。
-- 选「不包含才追加」而非固定终值：descr 基线会随现场修订与其他批次迁移变化，
-- 固定终值会覆盖现场已调整的研判表述；LOCATE + COALESCE 比 LIKE 更明确（无通配符/NULL 歧义）。
UPDATE script_nodes
   SET descr = CASE
         WHEN COALESCE(descr, '') = '' THEN '若影响扩大或等级上调，按升级流程重新研判、补报并按新等级续报，不在原节点内静默升级。'
         ELSE CONCAT(descr, ' 若影响扩大或等级上调，按升级流程重新研判、补报并按新等级续报，不在原节点内静默升级。')
       END
 WHERE id IN ('S02-3','S06-3','S08-3')
   AND LOCATE('按升级流程重新研判', COALESCE(descr, '')) = 0;
